  return this.ready().then(() => {
    // The signal may have been aborted before the server started listening: the
    // abort listener registered in `listen` already closed the instance, so the
    // server will emit neither 'listening' nor 'error' and the race below would
    // never settle.
    if (signal?.aborted) {
      throw abortError(signal)
    }

    let errEventHandler
    let listeningEventHandler
    let abortEventHandler
    function cleanup () {
      server.removeListener('error', errEventHandler)
      server.removeListener('listening', listeningEventHandler)
      if (abortEventHandler !== undefined) {
        signal.removeEventListener('abort', abortEventHandler)
      }
    }
    const errEvent = new Promise((resolve, reject) => {
      errEventHandler = (err) => {
        cleanup()
        this[kState].listening = false
        reject(err)
      }
      server.once('error', errEventHandler)
    })
    const listeningEvent = new Promise((resolve, reject) => {
      listeningEventHandler = () => {
        cleanup()
        this[kState].listening = true
        resolve(logServerAddress.call(this, server, listenOptions.listenTextResolver || defaultResolveServerListeningText))
      }
      server.once('listening', listeningEventHandler)
    })

    const events = [
      errEvent, // e.g invalid port range error is always emitted before the server listening
      listeningEvent
    ]

    if (signal !== undefined) {
      // an abort while the server is binding closes it without emitting any event
      events.push(new Promise((resolve, reject) => {
        abortEventHandler = () => {
          cleanup()
          this[kState].listening = false
          reject(abortError(signal))
        }
        signal.addEventListener('abort', abortEventHandler, { once: true })
      }))
    }

    server.listen(listenOptions)

    return Promise.race(events)
  })
}

function abortError (signal) {
  return signal.reason ?? new DOMException('This operation was aborted', 'AbortError')
}

