'use strict'
const { test } = require('node:test')
const Fastify = require('/tmp/cxbench-damage/55345987cb-hooks/fastify')

test('already aborted, promise', async (t) => {
  t.plan(2)
  const controller = new AbortController()
  controller.abort(new Error('aborting before actual start'))
  const fastify = Fastify()
  try {
    await fastify.listen({ port: 1234, signal: controller.signal })
    t.assert.fail('should not resolve')
  } catch (e) {
    t.assert.strictEqual(e.message, 'aborting before actual start')
  }
  t.assert.strictEqual(fastify.server.listening, false)
})

test('already aborted without reason, promise', async (t) => {
  t.plan(2)
  const controller = new AbortController()
  controller.abort()
  const fastify = Fastify()
  await t.assert.rejects(fastify.listen({ port: 1234, signal: controller.signal }), { name: 'AbortError' })
  t.assert.strictEqual(fastify.server.listening, false)
})

test('abort during boot, promise', async (t) => {
  t.plan(2)
  const controller = new AbortController()
  const fastify = Fastify()
  fastify.register(async () => { await new Promise(resolve => setTimeout(resolve, 50)) })
  const p = fastify.listen({ port: 1234, signal: controller.signal })
  controller.abort(new Error('aborted during boot'))
  await t.assert.rejects(p, { message: 'aborted during boot' })
  t.assert.strictEqual(fastify.server.listening, false)
})

